#include <bits/stdc++.h>
using namespace std;
namespace intervals {
#include "competition/models/interval_count.hpp"
#include "competition/models/interval_construct.hpp"
}
namespace trie {
#include "competition/xor/binary_trie.hpp"
}
namespace graph {
#include "competition/xor/graph_xor.hpp"
}
namespace energy {
#include "competition/xor/energy_intervals.hpp"
}
void require(bool ok, const string& message) {
    if(!ok) { cerr << "FAIL " << message << '\n'; exit(1); }
}
int brute_energy(const vector<int>& a) {
    int n=int(a.size())-1, ans=0;
    for(int l=1;l<=n;l++) for(int r=l+1;r<=n;r++) {
        int mx=0, value=0;
        for(int i=l;i<=r;i++) mx=max(mx,a[i]);
        for(int i=l;i<=r;i++) value^=(a[i]&mx);
        ans=max(ans,value);
    }
    return ans;
}
int encode(const vector<int>& a, int base, int shift) {
    int code=0, place=1;
    for(int value:a) { code+=(value+shift)*place; place*=base; }
    return code;
}
vector<int> decode(int code, int n, int base, int shift) {
    vector<int> a(n);
    for(int &value:a) { value=code%base-shift; code/=base; }
    return a;
}
int main() {
    long long energy_count=0;
    for(int n=2;n<=6;n++) {
        int total=1<<(3*n);
        for(int code=0;code<total;code++) {
            vector<int> a(n+1); int x=code;
            for(int i=1;i<=n;i++) { a[i]=x&7; x>>=3; }
            require(energy::energy_max(a,3)==brute_energy(a),"X11 direct interval oracle");
            energy_count++;
        }
    }
    int operation_count=0;
    for(int n=1;n<=3;n++) {
        int states=1;
        for(int i=0;i<n;i++) states*=9;
        vector<int> distance(states,-1);
        vector<int> zero(n,0); int start=encode(zero,9,4);
        queue<int> q; q.push(start); distance[start]=0;
        while(!q.empty()) {
            int code=q.front(); q.pop();
            vector<int> a=decode(code,n,9,4);
            for(int l=0;l<n;l++) for(int r=l;r<n;r++) {
                for(int delta=-8;delta<=8;delta++) {
                    if(delta==0) continue;
                    vector<int> b=a; bool valid=true;
                    for(int i=l;i<=r;i++) {
                        b[i]+=delta;
                        if(b[i]<-4 || b[i]>4) valid=false;
                    }
                    if(!valid) continue;
                    int next=encode(b,9,4);
                    if(distance[next]>=0) continue;
                    distance[next]=distance[code]+1; q.push(next);
                }
            }
        }
        int targets=1;
        for(int i=0;i<n;i++) targets*=5;
        for(int code=0;code<targets;code++) {
            vector<int> a=decode(code,n,5,2);
            vector<long long> b(1,0);
            for(int value:a) b.push_back(value);
            require(intervals::arbitrary_intervals_small(b)==distance[encode(a,9,4)],
                    "BM02 raw interval-operation BFS");
            operation_count++;
        }
    }
    vector<long long> alternating(20);
    for(int i=1;i<=19;i++) alternating[i]=(i&1);
    require(intervals::arbitrary_intervals_small(alternating)==10,"BM02 m=20");
    require(intervals::arbitrary_intervals_small({0})==0,"BM02 empty target");
    require(intervals::arbitrary_intervals_small({0,LLONG_MIN,LLONG_MAX})==2,"BM02 ll extremes");
    vector<vector<long long>> extreme_targets={
        {0,LLONG_MIN}, {0,LLONG_MAX}, {0,LLONG_MIN,LLONG_MAX},
        {0,LLONG_MAX,LLONG_MIN,LLONG_MAX,LLONG_MIN}
    };
    for(const auto &a:extreme_targets) {
        auto ops=intervals::construct_unit_intervals(a,0);
        require(ops.has_value(),"BM02 signed construction exists");
        vector<__int128_t> b(a.size()); __int128_t cost=0;
        for(auto op:*ops) {
            require(op.l>=1 && op.l<=op.r && op.r<int(a.size()) && op.cnt>0,
                    "BM02 valid compressed operation");
            require(op.sign==1 || op.sign==-1,"BM02 operation sign");
            for(int i=op.l;i<=op.r;i++) b[i]+=op.sign*op.cnt;
            cost+=op.cnt;
        }
        for(size_t i=1;i<a.size();i++) require(b[i]==(__int128_t)a[i],"BM02 reconstruction");
        require(cost==*intervals::unit_intervals(a,0),"BM01/BM02 optimum cost");
    }
    for(int width:{1,2,3,31,32,63,64}) {
        require(trie::trie_init(width,1+size_t(width)),"Trie initialize");
        require(trie::trie_insert(0) && trie::trie_insert(0),"Trie duplicates");
        auto saved_tree=trie::tree; auto saved_cnt=trie::cnt;
        unsigned long long high=1ULL<<(width-1);
        require(!trie::trie_insert(high),"Trie capacity failure");
        require(saved_tree==trie::tree && saved_cnt==trie::cnt,"Trie failed insert atomic");
        require(!trie::trie_init(65,100),"Trie invalid initialize");
        require(saved_tree==trie::tree && saved_cnt==trie::cnt && trie::bits==width,
                "Trie invalid initialize atomic");
        unsigned long long out=123;
        require(trie::trie_query(high,out) && out==high,"Trie full-width query");
        require(trie::trie_erase(0) && trie::cnt[1]==1,"Trie first duplicate removal");
        require(trie::trie_erase(0) && trie::cnt[1]==0,"Trie second duplicate removal");
        out=123;
        require(!trie::trie_query(0,out) && out==123,"Trie empty query output unchanged");
        require(!trie::trie_erase(0),"Trie missing removal");
        require(!trie::trie_insert(high),"Trie no reclaim contract");
        require(trie::trie_insert(0),"Trie reuse removed path");
    }
    require(trie::max_xor_pair({0})==0 && trie::cnt[1]==0,"Trie pair empty target resets");
    require(trie::max_xor_subarray({0})==0 && trie::cnt[1]==1,"Trie subarray empty prefix");
    vector<pair<int,int>> pairs;
    for(int u=1;u<=4;u++) for(int v=u+1;v<=4;v++) pairs.push_back({u,v});
    int graph_count=0;
    for(int code=0;code<729;code++) {
        graph::xor_graph_init(4);
        vector<tuple<int,int,int>> edges; int x=code;
        for(auto [u,v]:pairs) {
            int state=x%3; x/=3;
            if(state) { edges.push_back({u,v,state-1}); graph::xor_add_edge(u,v,state-1); }
        }
        bool possible=false;
        for(int labels=0;labels<16;labels++) {
            bool valid=true;
            for(auto [u,v,w]:edges) if((((labels>>(u-1))^(labels>>(v-1)))&1)!=w) valid=false;
            possible|=valid;
        }
        require(graph::xor_assign()==possible,"X05 exhaustive assignment oracle");
        require(graph::xor_assign()==possible,"X05 repeated assignment");
        if(possible) for(auto [u,v,w]:edges)
            require((graph::value[u]^graph::value[v])==(unsigned long long)w,"X05 witness");
        graph_count++;
    }
    cout << "PASS independent review: energy=" << energy_count
         << ", arbitrary-operation BFS=" << operation_count
         << ", m=20 DP, i128 extremes, Trie lifecycle, graphs=" << graph_count << '\n';
}
